.toolbar {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  align-items: center;
  margin: 24px 0;
}
.toolbar > input {
  flex: 1;
  min-width: 190px;
}
.select {
  background: #fff;
  border: 1px solid #e7e5e4;
  border-radius: 8px;
  min-height: 36px;
  padding: 6px 10px;
  font: inherit;
  max-width: 220px;
}
.datasets {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 20px 0;
}
.dataset {
  border: 0;
  border-radius: 20px;
  padding: 7px 11px;
  background: transparent;
  color: #78716c;
  font-size: 13px;
  cursor: pointer;
}
.selected {
  background: #171717;
  color: white;
}
.split {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(280px, 1fr);
  gap: 20px;
  align-items: start;
}
.stack {
  display: grid;
  gap: 20px;
}
.muted {
  font-size: 12px;
  color: #78716c;
}
.link {
  border: 0;
  padding: 0;
  background: none;
  font: inherit;
  color: inherit;
  cursor: pointer;
  text-align: left;
}
.link:hover {
  text-decoration: underline;
}
.details {
  margin: 0;
}
.details > div {
  display: grid;
  grid-template-columns: 100px 1fr;
  gap: 16px;
  padding: 14px 20px;
  border-top: 1px solid #e7e5e4;
}
.details dt {
  font-size: 11px;
  text-transform: uppercase;
  color: #78716c;
}
.details dd {
  margin: 0;
  font-size: 13px;
  overflow-wrap: anywhere;
}
.content {
  padding: 20px;
  font-size: 14px;
  line-height: 1.6;
}
.row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 20px;
  border-top: 1px solid #e7e5e4;
}
.row > span:last-child {
  color: #78716c;
}
.actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  padding: 14px 20px;
}
.footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 20px;
  background: #f5f5f4;
  font-size: 12px;
  color: #78716c;
}
.metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 24px 0;
}
.metric {
  padding: 18px;
  background: #fff;
  border: 1px solid #e7e5e4;
  border-radius: 10px;
}
.metric strong {
  display: block;
  font-size: 22px;
}
.metric span {
  font-size: 11px;
  color: #78716c;
  text-transform: uppercase;
}
.map {
  position: relative;
  min-height: 370px;
  overflow: hidden;
  background: #f5f5f4;
  border-radius: 8px;
  margin: 20px;
}
.mapReference {
  position: absolute;
  left: 50%;
  top: 18px;
  width: 556.412px;
  height: 302px;
  transform: translateX(-50%);
}
.mapReference img {
  position: absolute;
  display: block;
}
.mapControls {
  position: absolute;
  right: 12px;
  top: 12px;
  display: grid;
  gap: 8px;
}
.mapLegend {
  position: absolute;
  left: 16px;
  bottom: 16px;
  background: #fff;
  border: 1px solid #e7e5e4;
  padding: 8px;
  border-radius: 8px;
  font-size: 12px;
}
.geo {
  position: absolute;
  inset: 20px 10px;
  width: calc(100% - 20px);
  height: calc(100% - 40px);
}
.geo path {
  stroke: #b4b9b9;
  stroke-width: 0.5;
  cursor: pointer;
}
.geo path:hover {
  stroke: #0a0a0a;
  stroke-width: 1.5;
}
@media (max-width: 900px) {
  .split {
    grid-template-columns: 1fr;
  }
  .metrics {
    grid-template-columns: repeat(2, 1fr);
  }
}
